// Package notify: Telegram / Slack 푸시 (best-effort, 비동기).
package notify

import (
	"bytes"
	"encoding/json"
	"log/slog"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

const telegramAPI = "https://api.telegram.org"

type Notifier struct {
	TelegramToken string
	TelegramChat  string
	SlackWebhook  string
	http          *http.Client
	httpOnce      sync.Once
	telegramBase  string // "" 이면 telegramAPI (테스트에서 httptest 로 바꾼다)
}

func New(tgToken, tgChat, slack string) *Notifier {
	return &Notifier{TelegramToken: tgToken, TelegramChat: tgChat, SlackWebhook: slack,
		http: &http.Client{Timeout: 10 * time.Second}}
}

// client 는 http 클라이언트를 지연 초기화한다 — 구조체 리터럴로 만든 Notifier 도 Send 의 백그라운드 고루틴에서 nil 패닉으로 프로세스를 죽이지 않는다.
func (n *Notifier) client() *http.Client {
	n.httpOnce.Do(func() {
		if n.http == nil {
			n.http = &http.Client{Timeout: 10 * time.Second}
		}
	})
	return n.http
}

func (n *Notifier) Enabled() bool {
	return n != nil && ((n.TelegramToken != "" && n.TelegramChat != "") || n.SlackWebhook != "")
}

// Send 는 즉시 반환하고 백그라운드에서 전송한다. 실패는 로그만 남긴다.
func (n *Notifier) Send(text string) {
	if !n.Enabled() {
		return
	}
	go n.send(text)
}

// send 는 동기 전송 (테스트용 분리).
func (n *Notifier) send(text string) {
	c := n.client()
	if n.TelegramToken != "" && n.TelegramChat != "" {
		base := n.telegramBase
		if base == "" {
			base = telegramAPI
		}
		form := url.Values{"chat_id": {n.TelegramChat}, "text": {text}, "disable_web_page_preview": {"true"}}
		resp, err := c.PostForm(base+"/bot"+n.TelegramToken+"/sendMessage", form)
		if err != nil {
			slog.Warn("telegram 전송 실패", "err", err)
		} else {
			resp.Body.Close()
			if resp.StatusCode >= 400 {
				slog.Warn("telegram 응답 오류", "status", resp.StatusCode)
			}
		}
	}
	if n.SlackWebhook != "" {
		b, _ := json.Marshal(map[string]string{"text": strings.ReplaceAll(text, "**", "*")})
		resp, err := c.Post(n.SlackWebhook, "application/json", bytes.NewReader(b))
		if err != nil {
			slog.Warn("slack 전송 실패", "err", err)
		} else {
			resp.Body.Close()
		}
	}
}
package notify

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestEnabled(t *testing.T) {
	var nilN *Notifier
	if nilN.Enabled() {
		t.Fatal("nil notifier must be disabled")
	}
	cases := []struct {
		tok, chat, slack string
		want             bool
	}{
		{"", "", "", false},
		{"tok", "", "", false}, // 토큰만 있고 채팅 ID 가 없으면 무효
		{"", "chat", "", false},
		{"tok", "chat", "", true},
		{"", "", "https://hooks.slack/x", true},
	}
	for _, c := range cases {
		if got := New(c.tok, c.chat, c.slack).Enabled(); got != c.want {
			t.Errorf("Enabled(%q,%q,%q)=%v want %v", c.tok, c.chat, c.slack, got, c.want)
		}
	}
}

// 텔레그램: bot<token>/sendMessage 에 chat_id·text 폼으로 보낸다.
func TestSendTelegram(t *testing.T) {
	var gotPath, gotChat, gotText string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotPath = r.URL.Path
		if err := r.ParseForm(); err != nil {
			t.Errorf("parse form: %v", err)
		}
		gotChat, gotText = r.FormValue("chat_id"), r.FormValue("text")
		w.WriteHeader(200)
	}))
	defer srv.Close()
	n := New("TOKEN", "123", "")
	n.telegramBase = srv.URL
	n.send("hello **bold**")
	if gotPath != "/botTOKEN/sendMessage" || gotChat != "123" || gotText != "hello **bold**" {
		t.Fatalf("path=%q chat=%q text=%q", gotPath, gotChat, gotText)
	}
}

// 슬랙: JSON {"text": ...} 로 보내며 마크다운 굵게(**) 는 슬랙 문법(*) 으로 바꾼다.
func TestSendSlack(t *testing.T) {
	var got map[string]string
	var gotCT string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotCT = r.Header.Get("Content-Type")
		b, _ := io.ReadAll(r.Body)
		if err := json.Unmarshal(b, &got); err != nil {
			t.Errorf("body %q: %v", b, err)
		}
	}))
	defer srv.Close()
	n := New("", "", srv.URL)
	n.send("손익 **+1,000원**")
	if gotCT != "application/json" || got["text"] != "손익 *+1,000원*" {
		t.Fatalf("ct=%q body=%v", gotCT, got)
	}
}

// 구조체 리터럴로 만든 Notifier (http 필드 nil) 도 패닉 없이 전송한다.
func TestStructLiteralDoesNotPanic(t *testing.T) {
	hits := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { hits++ }))
	defer srv.Close()
	n := &Notifier{SlackWebhook: srv.URL}
	n.send("x")
	n.send("y")
	if hits != 2 {
		t.Fatalf("hits=%d", hits)
	}
	if n.http == nil || n.http.Timeout == 0 {
		t.Fatal("http client must be lazily initialised with a timeout")
	}
}

// 서버 오류(4xx/5xx) 나 연결 실패는 로그만 남기고 돌아온다 (best-effort).
func TestSendFailuresAreSwallowed(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(500) }))
	n := New("T", "C", srv.URL)
	n.telegramBase = srv.URL
	n.send("a")
	srv.Close()
	n.send("b") // 닫힌 서버 → 연결 실패
}
